FIX = Path(__file__).parent / "fixtures" / "visual"
UTC = timezone.utc
T_RTH = datetime(2026, 11, 10, 16, 30, tzinfo=UTC)          # Tue 10:30 CT


@lru_cache(maxsize=None)
def fixture(name):
    img = cv2.imread(str(FIX / f"{name}.png"))
    return img, json.loads((FIX / f"{name}.json").read_text()), tuple(ocr(img))


def prof(**kw):
    base = dict(plot_bottom=0.79, vwap_color=list(VWAP), ema_colors={"9": list(EMA9), "20": list(EMA20)})
    return ChartProfile(**{**base, **kw})


def read(name, **kw):
    img, truth, toks = fixture(name)
    return read_chart(img, prof(**kw), T_RTH, tokens=list(toks)), truth


# ---------------- profiles / region / window selection ----------------

def test_profile_validation_and_store(tmp_path):
    st = ProfileStore(tmp_path)
    p = st.save(prof(name="NQ 5m", region=[10, 20, 800, 600], root="NQ", timeframe="5Min"))
    assert p.id and st.get(p.id).region == [10, 20, 800, 600] and len(st.all()) == 1
    for bad in (dict(root="CL"), dict(timeframe="7Min"), dict(axis_mode="manual", axis_points=[[10, 1.0]]),
                dict(region=[0, 0, -1, 5]), dict(up_color=[300, 0, 0]), dict(capture_seconds=0.1)):
        with pytest.raises(ValueError):
            prof(**bad).validate()
    assert st.delete(p.id) and not st.all()
    assert prof(window_title_contains="TopstepX").matches("TopstepX - MNQZ6 - Google Chrome", "chrome.exe")
    assert not prof(window_title_contains="TopstepX", window_process="chrome.exe").matches("TopstepX", "msedge.exe")


# ---------------- OCR, axis, candles, indicators, volume ----------------

def test_reads_text_values_and_classes():
    r, t = read("mnq_5m_basic")
    assert r.ok and r.captured_at == T_RTH.isoformat()
    assert (r.instrument.value, r.instrument.cls) == ("MNQ", TEXT) and r.timeframe.value == "5Min"
    assert r.price.value == t["price"] and r.price.cls == TEXT and r.price.confidence >= 0.85
    assert r.bid.value == t["bid"] and r.ask.value == t["ask"] and r.bid.cls == TEXT
    assert r.axis["class"] == CALCULATED and r.axis["labels"] >= 6
    d = r.to_dict()
    assert all("confidence" in d[k] and "class" in d[k] for k in ("instrument", "timeframe", "price", "bid", "ask"))


def test_candle_recognition_against_ground_truth():
    for name in ("mnq_5m_basic", "mnq_5m_lines_on_top"):
        r, t = read(name)
        assert len(r.candles) == len(t["candles"])
        tick = 0.25
        for c, g in zip(r.candles, t["candles"], strict=True):
            assert abs(c.high - g["high"]) <= 2 * tick and abs(c.low - g["low"]) <= 2 * tick
            assert abs(c.open - g["open"]) <= 2 * tick and abs(c.close - g["close"]) <= 2 * tick
            assert c.direction == ("up" if g["close"] >= g["open"] else "down")
        vmax = max(g["volume"] for g in t["candles"])
        assert np.mean([abs(c.volume_rel - g["volume"] / vmax) for c, g in zip(r.candles, t["candles"], strict=True)]) < 0.03
        for nm, key in (("VWAP", "VWAP"), ("EMA 9", "EMA 9"), ("EMA 20", "EMA 20")):
            assert r.indicators[nm]["class"] == ESTIMATED
            assert abs(r.indicators[nm]["last"] - t["lines"][key][-1]) <= 4 * tick
    r, _ = read("mnq_5m_basic", ema_colors={"9": list(EMA9), "50": [10, 200, 10]})
    assert r.indicators["EMA 50"]["class"] == UNAVAILABLE                     # assigned color not on the chart: not guessed


def test_manual_axis_calibration_and_mismatch():
    auto, t = read("mnq_5m_basic")
    a, b = auto.axis["slope"], auto.axis["intercept"]
    pts = [[100.0, a * 100 + b], [500.0, a * 500 + b]]
    man, _ = read("mnq_5m_basic", axis_mode="manual", axis_points=pts)
    assert man.axis["mode"] == "manual" and [c.close for c in man.candles] == [c.close for c in auto.candles]
    wrong = [[100.0, pts[0][1] + 40], [500.0, pts[1][1] + 40]]                # chart panned/rescaled since calibration
    bad, t = read("mnq_5m_basic", axis_mode="manual", axis_points=wrong)
    assert not bad.ok and not bad.calibration_valid and bad.candles == [] and any("Calibration invalid" in p for p in bad.problems)
    assert bad.price.value == t["price"] and bad.price.cls == TEXT                  # text is still read, but analysis is paused
    assert vr.quality_gates(bad, "screen_capture", "", None).startswith("The chart couldn't be read")
    resized, _ = read("mnq_5m_basic", axis_mode="manual", axis_points=pts, axis_size=[1300, 820])
    assert not resized.calibration_valid and any("resized" in p for p in resized.problems)


def test_unreadable_price_and_uncertain_instrument_give_no_trade():
    r, _ = read("es_5m_no_tag")
    assert r.price.cls == UNAVAILABLE and r.price.value is None and not r.ok
    assert vr.quality_gates(r, "screen_capture", "", None).startswith("The chart couldn't be read")
    c, _ = read("mnq_5m_basic", root="ES")
    assert c.instrument.confidence < 0.6 and any("conflict" in p for p in c.problems)
    # still refused; the reason now names the conflict instead of a generic "Instrument uncertain"
    assert vr.quality_gates(c, "screen_capture", "", None) == "Chart doesn't match its setup: The chart shows MNQZ26, but this chart was set up for ES."


def test_confidence_falls_when_zoomed_out_and_blank_detected():
    r, _ = read("mnq_1m_zoomed_out")
    assert r.candle_confidence < 0.5 and any("narrow" in p for p in r.problems)
    assert vr.quality_gates(r, "screen_capture", "", None) is not None
    blank = read_chart(np.full((600, 900, 3), 20, np.uint8), prof(), T_RTH, tokens=[])
    assert not blank.ok and "Blank" in blank.problems[0]


