def test_candle_times_are_session_aligned_and_skip_the_break():
    clk = FuturesClock(fc.get("MNQ"))
    ts = candle_times(4, 300, datetime(2026, 11, 10, 23, 7, tzinfo=UTC), clk)     # 17:07 CT, minutes after the Globex open
    assert ts == [datetime(2026, 11, 10, 21, 50, tzinfo=UTC), datetime(2026, 11, 10, 21, 55, tzinfo=UTC),
                  datetime(2026, 11, 10, 23, 0, tzinfo=UTC), datetime(2026, 11, 10, 23, 5, tzinfo=UTC)]


def test_visual_frame_drops_levels_it_cannot_see():
    r, _ = read("mnq_5m_basic")
    spec = fc.get("MNQ")
    clk = FuturesClock(spec)
    bars, notes = bars_from_reading(r, 300, clk)
    assert bars[-1]["closed"] is False and all(b["closed"] for b in bars[:-1]) and any("calculated" in n for n in notes)
    F, n2 = visual_frame(bars, spec, clk, 300, screen_vwap=None, has_volume=True)
    assert F["vwap"].isna().all() and any("VWAP is unavailable" in n for n in n2)          # session open not on screen
    F2, n3 = visual_frame(bars, spec, clk, 300, screen_vwap=r.indicators["VWAP"]["values"], has_volume=True)
    # where candles cover the line it isn't visible: those bars stay NaN rather than being filled in
    assert F2["vwap"].notna().sum() >= 0.8 * len(F2) and any("read from the chart" in n for n in n3)


# ---------------- monitor: window, capture, frozen, obscured, layout, alerts ----------------

class FakeWin:
    def __init__(self):
        self.min, self.cover, self.alive = False, False, True

    def exists(self, h):
        return self.alive

    def minimized(self, h):
        return self.min

    def obscured(self, h, region):
        return self.cover

    def rect(self, h):
        return (0, 0, 1400, 820)


class FakeAlerts:
    def __init__(self):
        self.sent = []

    def emit(self, category, severity, title, body, *, key, fingerprint, symbol=None, data=None, link=None):
        self.sent.append((key, title))
        return True


class Clock:
    def __init__(self, t):
        self.t = t

    def __call__(self):
        return self.t


def make_monitor(futures_svc, frame_fn, windows, clock, alerts=None, **pkw):
    class Store:
        def __init__(self):
            self.p = prof(**{"id": "p1", "name": "MNQ 5m", "window_title_contains": "TopstepX", **pkw})

        def all(self):
            return [self.p]
    win = FakeWin()
    _, _, toks = fixture("mnq_5m_basic")
    m = VisualMonitor(Store(), futures_svc, alerts or FakeAlerts(), None, None, capture_fn=frame_fn, list_fn=lambda: windows,
                      win=win, now=clock, ocr_fn=lambda img: list(toks))
    m._sync_profiles()
    m.state = "running"
    return m, m.runtimes["p1"], win


@pytest.fixture
def fut(tmp_path):
    from app.config import Settings
