async def test_window_missing_minimized_capture_failure_obscured_layout(fut):
    img, _, _ = fixture("mnq_5m_basic")
    clock = Clock(T_RTH)
    alerts = FakeAlerts()
    state = {"frame": img, "method": "printwindow"}
    m, rt, win = make_monitor(fut, lambda t: (state["frame"], state["method"]), [], clock, alerts)
    await m.tick(rt)
    assert rt.status == "disconnected" and rt.recommendation["action"] == "NO TRADE" and "No open window" in rt.reason
    await m.tick(rt)
    assert len([a for a in alerts.sent if "chart_missing" in a[0]]) == 1                  # duplicate alert suppressed
    m.list_fn = lambda: [{"kind": "window", "id": 42, "title": "TopstepX | MNQZ6", "process": "chrome.exe"}]
    win.min = True
    await m.tick(rt)
    assert rt.status == "disconnected" and "minimized" in rt.reason
    win.min = False
    state["frame"], state["method"] = None, "PrintWindow returned nothing"
    await m.tick(rt)
    assert rt.status == "unreadable" and "Capture failed" in rt.reason
    state["frame"], state["method"] = img, "mss-region (window must be visible)"
    win.cover = True
    await m.tick(rt)
    assert rt.status == "unreadable" and "covers" in rt.reason
    win.cover = False
    state["method"] = "printwindow"
    rt.profile.window_size = [1600, 900]
    await m.tick(rt)
    assert rt.status == "unreadable" and "Layout changed" in rt.reason
    rt.profile.window_size = [1400, 820]
    await m.tick(rt)
    assert rt.status == "screen_capture" and rt.reading.ok
    rec = rt.recommendation
    assert rec["action"] in ("NO TRADE", "WAIT", "LONG", "SHORT") and rec["captured_at"] == T_RTH.isoformat()
    assert rec["data_label"] == "LIVE VISUAL OBSERVATION" and "not an exchange feed" in rec["source"]


async def test_frozen_chart_and_stale(fut):
    img, _, _ = fixture("mnq_5m_basic")
    clock = Clock(T_RTH)
    m, rt, _ = make_monitor(fut, lambda t: (img, "printwindow"),
                            [{"kind": "window", "id": 42, "title": "TopstepX", "process": "chrome.exe"}], clock, frozen_seconds=60)
    await m.tick(rt)
    assert rt.status == "screen_capture"
    clock.t = T_RTH + timedelta(seconds=30)
    await m.tick(rt)
    assert rt.status == "screen_capture"                       # unchanged but not long enough to be frozen
    clock.t = T_RTH + timedelta(seconds=61)
    await m.tick(rt)
    assert rt.status == "stale" and "frozen" in rt.reason and rt.recommendation["action"] == "NO TRADE"
    # a changed picture brings it back
    img2 = img.copy()
    img2[300:302, 1065:1067] = (154, 166, 38)                  # the last candle grows by a couple of pixels
    m.capture_fn = lambda t: (img2, "printwindow")
    clock.t = T_RTH + timedelta(seconds=63)
    await m.tick(rt)
    assert rt.status == "screen_capture"


async def test_layout_change_detected_from_the_chart_itself(fut):
    img, _, _ = fixture("mnq_5m_basic")
    clock = Clock(T_RTH)
    m, rt, _ = make_monitor(fut, lambda t: (img, "printwindow"), [{"kind": "window", "id": 42, "title": "TopstepX", "process": None}], clock)
    await m.tick(rt)
    rt.signature = {**rt.signature, "axis_left": rt.signature["axis_left"] - 80}       # as if the axis had moved
    rt.thumb = None
    await m.tick(rt)
    assert rt.status == "unreadable" and "layout changed" in rt.reason.lower()
    rt.thumb = None
    await m.tick(rt)
    assert rt.status == "screen_capture"                       # same new layout twice: accepted


# ---------------- recommendations: risk engine and evidence ----------------

def _decision(outcome, plan, steps=None):
    return fp.Decision("d1", "MNQZ26", "MNQ", T_RTH.isoformat(), T_RTH.isoformat(), outcome,
                       "LONG" if outcome == "APPROVED" else fp.ACTION_OF.get(outcome, outcome), "r", steps or [], plan)


async def test_recommendation_uses_risk_engine_and_keeps_evidence_rule(fut, monkeypatch):
    r, _ = read("mnq_5m_basic")
    spec = fc.get("MNQ")
    clk = FuturesClock(spec)
    bars, _ = bars_from_reading(r, 300, clk)
    F, _ = visual_frame(bars, spec, clk, 300, screen_vwap=r.indicators["VWAP"]["values"])
    seen = {}
    plan = {"setup": "vwap_reclaim", "direction": "long", "entry": 24970.0, "stop": 24960.0, "target": 24990.0, "invalidation": "below VWAP",
            "evidence_short": "inconclusive", "risk_check": {"ok": True, "problems": [], "warnings": []}, "suggested_contracts": 2}

    def fake_run(F5, F15, contract, label, evidence, **kw):
        seen.update(kw, label=label)
        return _decision(seen.get("_outcome", "WATCH_ONLY"), plan)
    monkeypatch.setattr(fp, "run", fake_run)
    rec = vr.build(r, F, None, status="screen_capture", status_reason="", profile=prof(), futures=fut, now=T_RTH)
    assert seen["risk_engine"] is not None and seen["snapshot"] is not None and seen["check_unvalidated"] is True
    assert seen["label"]["status"] == "screen_capture" and seen["current_price"] == r.price.value
    assert rec["action"] == "WAIT" and rec["potential"] == "LONG" and "isn't a validated strategy" in rec["reason"]
    assert (rec["target_1"], rec["target_2"], rec["reward_risk"]) == (24980.0, 24990.0, 2.0)
    for k in ("contract", "direction", "observed_price", "entry_zone", "stop", "setup", "evidence", "invalidation", "timeframe",
              "data_confidence", "captured_at"):
        assert k in rec
    plan["risk_check"] = {"ok": False, "problems": ["Daily loss limit reached."], "warnings": []}
    seen["_outcome"] = "REJECTED"
    assert vr.build(r, F, None, status="screen_capture", status_reason="", profile=prof(), futures=fut, now=T_RTH)["action"] == "NO TRADE"
    seen["_outcome"] = "APPROVED"
    plan["risk_check"] = {"ok": True, "problems": [], "warnings": []}
    ap = vr.build(r, F, None, status="screen_capture", status_reason="", profile=prof(), futures=fut, now=T_RTH)
    assert ap["action"] == "LONG" and ap["potential"] is None
    # EXIT on the observed (text) price through the stop of an active recommendation
    active = {"contract": "MNQZ26", "direction": "long", "stop": r.price.value + 1, "target_2": r.price.value + 50, "decision_id": "d1"}
    ex = vr.build(r, F, None, status="screen_capture", status_reason="", profile=prof(), futures=fut, now=T_RTH, prev_active=active)
    assert ex["action"] == "EXIT" and ex["exit_kind"] == "stop"
    # anything but SCREEN_CAPTURE -> NO TRADE with the reason
    st = vr.build(r, F, None, status="stale", status_reason="Chart frozen", profile=prof(), futures=fut, now=T_RTH)
    assert st["action"] == "NO TRADE" and "STALE" in st["reason"]


def test_pipeline_check_unvalidated_runs_risk_steps_but_never_approves():
    """On real recorded ES bars: a setup that stops at the evidence step normally gets checked through steps 8-12 when asked,
    and the outcome still isn't APPROVED."""
    df = pd.read_csv(Path(__file__).parent / "fixtures" / "es_5m_2026-10-25_11-06.csv", index_col=0, parse_dates=True)
    spec = fc.get("ES")
    clk = FuturesClock(spec)
    bars = [{"ts": t.to_pydatetime(), "open": r.Open, "high": r.High, "low": r.Low, "close": r.Close, "volume": r.Volume}
            for t, r in df.iterrows()]
    F = ff.build(ff.bars_to_frame(bars, clk), spec, clk, bar_minutes=5)
    con = fc.front_contract("ES", F["ts"].iloc[-1].date())
    lab = {"status": "replay", "provider": "test", "age_seconds": 0, "validation": {"ok": True}}
    found = None
    for i in range(200, len(F)):
        sub = F.iloc[: i + 1]
        now = sub["ts"].iloc[-1].to_pydatetime() + timedelta(minutes=5)
        d = fp.run(sub, None, con, lab, {}, now=now, validated=set())
        if d.outcome == "WATCH_ONLY" and d.steps[6]["passed"] is False:
            found = (sub, now)
            break
    assert found, "no unvalidated setup in the recorded data"
    sub, now = found
    d2 = fp.run(sub, None, con, lab, {}, now=now, validated=set(), check_unvalidated=True)
    assert d2.outcome != "APPROVED"
    assert any(s["n"] >= 8 and s["passed"] is not None for s in d2.steps[7:12])


async def test_alerts_once_per_state_change(fut):
    m, rt, _ = make_monitor(fut, lambda t: (None, "x"), [], Clock(T_RTH), FakeAlerts())
    rec = {"action": "WAIT", "potential": "LONG", "setup": "vwap_reclaim", "direction": "long", "entry": 1.0, "stop": 0.5,
           "target_1": 1.5, "target_2": 2.0, "contract": "MNQZ26", "data_confidence": 0.8, "captured_at": T_RTH.isoformat(), "reason": "x"}
    m._alerts_for(rt, rec, T_RTH)
    m._alerts_for(rt, rec, T_RTH)
    pots = [a for a in m.alerts.sent if "potential" in a[0]]
    assert len(pots) == 1
    inval = {**rec, "action": "NO TRADE", "potential": None, "observed_price": 0.4}
    m._alerts_for(rt, inval, T_RTH)
    m._alerts_for(rt, inval, T_RTH)
    assert len([a for a in m.alerts.sent if ":invalid" in a[0]]) == 1
    ent = {**rec, "action": "LONG", "potential": None, "decision_id": "abc"}
    m._alerts_for(rt, ent, T_RTH)
    m._alerts_for(rt, ent, T_RTH)
    assert len([a for a in m.alerts.sent if ":entry" in a[0]]) == 1


