from .test_futures_api import client  # noqa: E402,F401


async def test_api_profiles_upload_read_control_and_calibration(client):  # noqa: F811
    c, app = client
    w = (await c.get("/api/visual/windows")).json()
    assert "windows" in w and (w["window_capture_supported"] or w["note"])
    assert (await c.post("/api/visual/start")).status_code == 400                       # no profile yet
    body = prof(name="MNQ 5m").to_dict()
    saved = (await c.post("/api/visual/profiles", json=body)).json()
    assert saved["id"] and (await c.get("/api/visual/profiles")).json()["profiles"][0]["name"] == "MNQ 5m"
    assert (await c.post("/api/visual/profiles", json={**body, "root": "CL"})).status_code == 422
    png = (FIX / "mnq_5m_basic.png").read_bytes()
    r = (await c.post("/api/visual/upload-read", files={"file": ("c.png", png, "image/png")}, data={"profile": json.dumps(body)})).json()
    _, truth, _ = fixture("mnq_5m_basic")
    assert r["price"]["value"] == truth["price"] and r["price"]["class"] == TEXT and len(r["candles"]) == len(truth["candles"])
    st = (await c.post("/api/visual/start")).json()
    assert st["state"] == "running" and saved["id"] in st["charts"]
    assert (await c.post("/api/visual/pause")).json()["state"] == "paused"
    assert (await c.post("/api/visual/stop")).json()["state"] == "stopped"
    # real-screenshot calibration workflow, scored with the chart profile (here on a synthetic image: marked synthetic)
    g = truth["candles"][-2]
    cal = (await c.post("/api/screen/calibration/sample", files={"file": ("c.png", png, "image/png")},
                        data={"ticker": "MNQZ26", "timeframe": "5m", "price": str(truth["price"]), "platform": "topstepx", "synthetic": "true",
                              "profile_id": saved["id"], "last_open": str(g["open"]), "last_high": str(g["high"]),
                              "last_low": str(g["low"]), "last_close": str(g["close"])})).json()
    res = cal["result"]
    assert res["ticker"]["ok"] and res["timeframe"]["ok"] and res["price"]["ok"] and res["last_candle"]["ok"]
    assert cal["platform"].startswith("topstepx-visual") and cal["synthetic"]
    rep = (await c.get("/api/screen/calibration")).json()["report"]
    assert rep["real_samples"] == 0                                                       # synthetic never counts
    assert (await c.delete(f"/api/visual/profiles/{saved['id']}")).json()["deleted"] == saved["id"]


